#include <iostream>
#include <optional>
std::optional<unsigned long long> factorial(unsigned n) {
    unsigned long long result = 1;
    for (unsigned i = 2; i <= n; ++i) {
        if (result > ~0ULL / i) return std::nullopt;
        result *= i;
    }
    return result;
}
unsigned long long fibonacci(unsigned n) {
    unsigned long long a = 0, b = 1;
    for (unsigned i = 0; i < n; ++i) { const auto next = a + b; a = b; b = next; }
    return a;
}
int main() { std::cout << *factorial(5) << ' ' << fibonacci(7) << '\n'; }
